   436  /* Sort by merge sort */
   437  static void pairing_nodes_front_back_split(FriBidiPairingNode *source,
   438                                             /* output */
   439                                             FriBidiPairingNode **front,
   440                                             FriBidiPairingNode **back)
   441  {
   442    FriBidiPairingNode *pfast, *pslow;
   443    if (!source || !source->next)
   444      {
   445        *front = source;
   446        *back = NULL;
   447      }
   448    else
   449      {
   450        pslow = source;
   451        pfast = source->next;
   452        while (pfast)
   453          {
   454            pfast= pfast->next;
   455            if (pfast)
   456              {
   457                pfast = pfast->next;
   458                pslow = pslow->next;
   459              }
   460          }
   461        *front = source;
   462        *back = pslow->next;
   463        pslow->next = NULL;
   464      }
   465  }
