    37  FriBidiRun *
    38  new_run (
    39    void
    40  )
    41  {
    42    register FriBidiRun *run;
    43
    44    run = fribidi_malloc (sizeof (FriBidiRun));
    45
    46    if LIKELY
    47      (run)
    48      {
    49        run->len = run->pos = run->level = run->isolate_level = 0;
    50        run->next = run->prev = run->prev_isolate = run->next_isolate = NULL;
    51      }
    52    return run;
    53  }
